meta.query:
SELECT DISTINCT ?person ?occupation ?birthplace ?birthDate ?deathDate ?coordinates ?image WHERE {
  VALUES ?occupation { wd:Q33999 wd:Q36180 wd:Q2526255 wd:Q28389 wd:Q49757 wd:Q483501 wd:Q3387717 wd:Q83307 }
  ?person wdt:P31 wd:Q5;
          wdt:P106 ?occupation;
          wdt:P19 ?birthplace.
  ?birthplace wdt:P131* wd:Q1185.
  OPTIONAL { ?person wdt:P569 ?birthDate. }
  OPTIONAL { ?person wdt:P570 ?deathDate. }
  OPTIONAL { ?birthplace wdt:P625 ?coordinates. }
  OPTIONAL { ?person wdt:P18 ?image. }
}
